package com.pohloadingtips;

import java.util.List;
import lombok.Value;

/**
 * A meme card: one to three OSRS item sprites (drawn by the player's own
 * RuneLite client, so no images are bundled or downloaded) with an original
 * top and bottom caption.
 */
@Value
public class Meme
{
	List<Integer> itemIds;
	String top;
	String bottom;
}

package com.pohloadingtips;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads meme cards from memes.txt ("itemId,itemId|TOP|BOTTOM" per line, built by
 * scripts/resolve-memes.mjs) and deals them like a shuffled deck.
 */
@Slf4j
class MemeRepository
{
	private final List<Meme> all = new ArrayList<>();
	private final Deque<Meme> deck = new ArrayDeque<>();

	MemeRepository()
	{
		try (InputStream in = MemeRepository.class.getResourceAsStream("memes.txt"))
		{
			if (in == null)
			{
				log.warn("memes.txt not found");
				return;
			}
			BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			String line;
			while ((line = reader.readLine()) != null)
			{
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#")) continue;
				String[] parts = line.split("\\|", 3);
				if (parts.length != 3) continue;
				List<Integer> ids = new ArrayList<>();
				for (String id : parts[0].split(","))
				{
					try
					{
						ids.add(Integer.parseInt(id.trim()));
					}
					catch (NumberFormatException e)
					{
						log.warn("Bad item id in meme: {}", line);
					}
				}
				if (!ids.isEmpty()) all.add(new Meme(ids, parts[1].trim(), parts[2].trim()));
			}
		}
		catch (IOException e)
		{
			log.warn("Unable to load memes", e);
		}
	}

	int size()
	{
		return all.size();
	}

	Meme next()
	{
		if (all.isEmpty()) return null;
		if (deck.isEmpty())
		{
			List<Meme> shuffled = new ArrayList<>(all);
			Collections.shuffle(shuffled);
			deck.addAll(shuffled);
		}
		return deck.poll();
	}
}

package com.pohloadingtips;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(PohLoadingTipsConfig.GROUP)
public interface PohLoadingTipsConfig extends Config
{
	String GROUP = "pohloadingtips";

	@Range(min = 16, max = 40)
	@ConfigItem(
		keyName = "textSize",
		name = "Text size",
		description = "Size of the meme captions. Text shrinks automatically if it won't fit.",
		position = 0
	)
	default int textSize()
	{
		return 24;
	}
}

package com.pohloadingtips;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws a meme card over the house loading screen, on a classic OSRS
 * dark brown stone panel.
 */
class PohLoadingTipsOverlay extends Overlay
{
	// Classic OSRS interface palette
	private static final Color SCREEN_TOP = new Color(0x1E1912);
	private static final Color SCREEN_BOTTOM = new Color(0x0B0906);
	private static final Color PANEL_FILL = new Color(0x3E3529);
	private static final Color PANEL_FILL_DARK = new Color(0x2E271E);
	private static final Color BORDER_OUTER = new Color(0x0E0E0C);
	private static final Color BORDER_LIGHT = new Color(0x5A5245);
	private static final Color BORDER_DARK = new Color(0x241F18);

	private static final int MARGIN = 20;
	private static final int PANEL_MAX_WIDTH = 620;

	private final Client client;
	private final PohLoadingTipsPlugin plugin;
	private final PohLoadingTipsConfig config;

	private final ItemManager itemManager;

	@Inject
	PohLoadingTipsOverlay(Client client, PohLoadingTipsPlugin plugin, PohLoadingTipsConfig config, ItemManager itemManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Meme meme = plugin.getCurrentMeme();
		if (meme != null)
		{
			renderMemeCard(g, meme);
		}
		return null;
	}

	// ---------------------------------------------------------------- memes

	private static final Color MEME_TEXT = Color.WHITE;

	private void renderMemeCard(Graphics2D g, Meme meme)
	{
		if (System.currentTimeMillis() < plugin.getPreviewUntil())
		{
			renderMemeScreen(g, viewport(), meme); // ::pohmeme preview
			return;
		}
		if (plugin.isLoadingScreenVisible())
		{
			Widget w = plugin.getPohLoadingWidget();
			Rectangle area = w != null ? w.getBounds() : null;
			if (area == null || area.width < 50 || area.height < 50)
			{
				area = viewport();
			}
			renderMemeScreen(g, area, meme);
		}
	}

	private void renderMemeScreen(Graphics2D g, Rectangle area, Meme meme)
	{
		Paint oldPaint = g.getPaint();
		g.setPaint(new GradientPaint(0, area.y, SCREEN_TOP, 0, area.y + area.height, SCREEN_BOTTOM));
		g.fillRect(area.x, area.y, area.width, area.height);
		g.setPaint(oldPaint);

		int panelW = Math.min(area.width - MARGIN * 2, PANEL_MAX_WIDTH);
		int pad = 16;
		int textW = panelW - pad * 2;
		int n = meme.getItemIds().size();

		// Sprites are 36x32; scale up by a whole number so the pixel art stays crisp.
		int scale = 4;
		while (scale > 1 && (n * 36 * scale + (n - 1) * 12 > textW || 32 * scale > area.height / 3))
		{
			scale--;
		}
		int spriteW = 36 * scale;
		int spriteH = 32 * scale;

		int size = Math.max(16, config.textSize() + 4);
		Font font;
		List<String> top;
		List<String> bottom;
		FontMetrics fm;
		do
		{
			font = FontManager.getRunescapeBoldFont().deriveFont(Font.PLAIN, (float) size);
			fm = g.getFontMetrics(font);
			top = wrap(meme.getTop(), fm, textW);
			bottom = wrap(meme.getBottom(), fm, textW);
			size -= 2;
		}
		while ((top.size() + bottom.size()) * fm.getHeight() + spriteH + pad * 4 > area.height - MARGIN * 2 && size >= 14);

		int panelH = pad + top.size() * fm.getHeight() + pad + spriteH + pad + bottom.size() * fm.getHeight() + pad;
		int px = area.x + (area.width - panelW) / 2;
		int py = area.y + (area.height - panelH) / 2;
		drawStonePanel(g, px, py, panelW, panelH);

		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setFont(font);
		int y = py + pad;
		for (String line : top)
		{
			drawOutlined(g, line, px, panelW, y + fm.getAscent(), scale > 2 ? 2 : 1);
			y += fm.getHeight();
		}
		y += pad;

		Object oldInterp = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		int rowW = n * spriteW + (n - 1) * 12;
		int sx = px + (panelW - rowW) / 2;
		for (int id : meme.getItemIds())
		{
			BufferedImage img = itemManager.getImage(id);
			if (img != null)
			{
				g.drawImage(img, sx, y, spriteW, spriteH, null);
			}
			sx += spriteW + 12;
		}
		if (oldInterp != null) g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, oldInterp);
		y += spriteH + pad;

		for (String line : bottom)
		{
			drawOutlined(g, line, px, panelW, y + fm.getAscent(), scale > 2 ? 2 : 1);
			y += fm.getHeight();
		}
	}


	/** Classic meme text: white with a black outline, centred. */
	private static void drawOutlined(Graphics2D g, String s, int x, int w, int baseline, int outline)
	{
		FontMetrics fm = g.getFontMetrics();
		int sx = x + (w - fm.stringWidth(s)) / 2;
		g.setColor(Color.BLACK);
		for (int dx = -outline; dx <= outline; dx++)
		{
			for (int dy = -outline; dy <= outline; dy++)
			{
				if (dx != 0 || dy != 0) g.drawString(s, sx + dx, baseline + dy);
			}
		}
		g.setColor(MEME_TEXT);
		g.drawString(s, sx, baseline);
	}

	private Rectangle viewport()
	{
		return new Rectangle(client.getViewportXOffset(), client.getViewportYOffset(),
			client.getViewportWidth(), client.getViewportHeight());
	}

	// ---------------------------------------------------------------- helpers

	/** OSRS-style beveled stone panel. */
	private static void drawStonePanel(Graphics2D g, int x, int y, int w, int h)
	{
		Paint old = g.getPaint();
		g.setPaint(new GradientPaint(0, y, PANEL_FILL, 0, y + h, PANEL_FILL_DARK));
		g.fillRect(x, y, w, h);
		g.setPaint(old);

		g.setColor(BORDER_OUTER);
		g.drawRect(x, y, w - 1, h - 1);
		g.setColor(BORDER_LIGHT);
		g.drawLine(x + 1, y + 1, x + w - 2, y + 1);
		g.drawLine(x + 1, y + 1, x + 1, y + h - 2);
		g.setColor(BORDER_DARK);
		g.drawLine(x + 1, y + h - 2, x + w - 2, y + h - 2);
		g.drawLine(x + w - 2, y + 1, x + w - 2, y + h - 2);
		g.setColor(BORDER_OUTER);
		g.drawRect(x + 3, y + 3, w - 7, h - 7);
	}

	private static List<String> wrap(String text, FontMetrics fm, int maxWidth)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split("\\s+"))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(candidate) <= maxWidth || line.length() == 0)
			{
				line.setLength(0);
				line.append(candidate);
			}
			else
			{
				lines.add(line.toString());
				line.setLength(0);
				line.append(word);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}
}

package com.pohloadingtips;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "POH Loading Screen",
	description = "Replaces the house loading screen with original OSRS meme cards",
	tags = {"poh", "house", "construction", "loading", "memes"}
)
public class PohLoadingTipsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PohLoadingTipsOverlay overlay;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	private final MemeRepository memes = new MemeRepository();

	/** Meme for the current (or most recent) loading screen. */
	@Getter
	private Meme currentMeme;

	/** Picked ahead of time so its sprites are already loaded when the screen appears. */
	private Meme nextMeme;

	/** "::pohmeme" shows the next meme card on screen until this time (System.currentTimeMillis). */
	@Getter
	private long previewUntil;

	/** Whether the POH loading screen is up right now. */
	@Getter
	private boolean loadingScreenVisible;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		prepareNextMeme();
		log.debug("POH Loading Screen started with {} memes", memes.size());
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		loadingScreenVisible = false;
		currentMeme = null;
		nextMeme = null;
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted e)
	{
		if (!"pohmeme".equalsIgnoreCase(e.getCommand()) || nextMeme == null) return;
		currentMeme = nextMeme;
		previewUntil = System.currentTimeMillis() + 8000;
		prepareNextMeme();
	}

	/** Picks the next meme and asks RuneLite to load its sprites now, not mid-loading-screen. */
	private void prepareNextMeme()
	{
		nextMeme = memes.next();
		Meme m = nextMeme;
		if (m != null)
		{
			clientThread.invokeLater(() -> m.getItemIds().forEach(itemManager::getImage));
		}
	}

	/**
	 * Polled every client frame rather than relying on widget load/close events,
	 * so we always know exactly whether the house loading screen is on screen.
	 */
	@Subscribe
	public void onClientTick(ClientTick tick)
	{
		boolean visible = getPohLoadingWidget() != null;
		if (visible == loadingScreenVisible)
		{
			return;
		}

		loadingScreenVisible = visible;
		if (visible && nextMeme != null)
		{
			currentMeme = nextMeme;
			prepareNextMeme();
		}
	}

	/** The widget area the loading screen covers, or null if it isn't showing. */
	Widget getPohLoadingWidget()
	{
		Widget w = client.getWidget(InterfaceID.PohLoading.UNIVERSE);
		if (w == null || w.isHidden())
		{
			w = client.getWidget(InterfaceID.PohLoading.UNIVERSE_RECT0);
		}
		return w != null && !w.isHidden() ? w : null;
	}

	@Provides
	PohLoadingTipsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PohLoadingTipsConfig.class);
	}
}

package com.pohloadingtips;

import java.util.HashSet;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class MemeRepositoryTest
{
	@Test
	public void allMemesLoadWithItemsAndCaptions()
	{
		MemeRepository repo = new MemeRepository();
		assertEquals(100, repo.size());
		Set<String> seen = new HashSet<>();
		for (int i = 0; i < repo.size(); i++)
		{
			Meme m = repo.next();
			assertNotNull(m);
			assertTrue("1-3 sprites", m.getItemIds().size() >= 1 && m.getItemIds().size() <= 3);
			assertTrue("valid item ids", m.getItemIds().stream().allMatch(id -> id > 0 && id < 40000));
			assertTrue(!m.getTop().isEmpty() && !m.getBottom().isEmpty());
			seen.add(m.getTop() + m.getBottom());
		}
		assertEquals("a full deck shows every meme once before repeating", 100, seen.size());
	}
}

